function subsets(nums) {
    const res = [], sub = [];
    function dfs(i) {
        if (i >= nums.length) {
            res.push([...sub]);
            return;
        }
        sub.push(nums[i]);
        dfs(i + 1);
        sub.pop();
        dfs(i + 1);
    }
    dfs(0);
    return res;
}
